// Generates admin/src/kiln-colors.generated.css: every colour declaration of admin/src/style.css re-emitted with a warm
// palette under :root[data-skin=kiln]. The Dream admin stylesheet stays untouched; run `npm run build:admin-skin` after
// changing any colour in it (tests/admin-skin.test.mjs fails while the generated file is out of date).
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const SKIN=':root[data-skin=kiln]';
const HEX=/#[0-9a-fA-F]{3,8}\b/g;
const HAS_HEX=/#[0-9a-fA-F]{3,8}\b/;

function parseHex(hex){
 let h=hex.slice(1);
 if(h.length===3||h.length===4)h=[...h].map(c=>c+c).join('');
 if(h.length!==6&&h.length!==8)throw new Error(`Unsupported colour ${hex}`);
 return {r:parseInt(h.slice(0,2),16),g:parseInt(h.slice(2,4),16),b:parseInt(h.slice(4,6),16),a:h.length===8?parseInt(h.slice(6,8),16):null};
}
function toHsl({r,g,b}){
 r/=255;g/=255;b/=255;const max=Math.max(r,g,b),min=Math.min(r,g,b),l=(max+min)/2,d=max-min;
 if(!d)return {h:0,s:0,l};
 const s=d/(1-Math.abs(2*l-1));
 const h=max===r?((g-b)/d+(g<b?6:0)):max===g?(b-r)/d+2:(r-g)/d+4;
 return {h:h*60,s,l};
}
function fromHsl({h,s,l}){
 const c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs((h/60)%2-1)),m=l-c/2;
 const [r,g,b]=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];
 return {r:Math.round((r+m)*255),g:Math.round((g+m)*255),b:Math.round((b+m)*255)};
}
const clamp=(v,min,max)=>Math.min(max,Math.max(min,v));
const byte=n=>n.toString(16).padStart(2,'0');

// Dream's admin palette is slate blue with one bright blue accent. Kiln keeps lightness and alpha, so contrast and
// layering are unchanged, and swaps the hue: slate -> warm neutral, bright blue -> coral. Green, red and amber
// status colours keep their hue so success/error/private still read the same way.
export function warmColour(hex){
 const parsed=parseHex(hex),{h,s,l}=toHsl(parsed);
 let out;
 if(s<.08)out=l>.85?{r:244,g:232,b:220}:parsed;                     // white overlays become warm white, black stays
 else if(h>=185&&h<=260){
  if(s>=.5&&l>=.4&&l<.87)out=fromHsl({h:14,s:.62,l:clamp(l-.08,.45,.85)}); // bright blue accent -> coral (near-white tints stay neutral)
  else out=fromHsl({h:30,s:Math.min(s*.35,.18),l});                  // slate neutral -> warm neutral
 }else out=parsed;
 const alpha=parsed.a===null?'':byte(parsed.a);
 return '#'+byte(out.r)+byte(out.g)+byte(out.b)+alpha;
}

// Splits on a separator that is not inside parentheses or quotes.
function splitTop(text,separator){
 const parts=[];let depth=0,quote='',start=0;
 for(let i=0;i<text.length;i++){
  const c=text[i];
  if(quote){if(c===quote)quote='';continue}
  if(c==='"'||c==="'")quote=c;else if(c==='(')depth++;else if(c===')')depth--;
  else if(c===separator&&depth===0){parts.push(text.slice(start,i));start=i+1}
 }
 parts.push(text.slice(start));return parts;
}

// Minimal CSS block parser: returns [{type:'rule',selector,body}|{type:'at',prelude,children}].
function parseBlocks(css){
 const nodes=[];let i=0;
 while(i<css.length){
  const open=css.indexOf('{',i);if(open<0)break;
  const prelude=css.slice(i,open).trim();let depth=1,j=open+1;
  while(j<css.length&&depth){if(css[j]==='{')depth++;else if(css[j]==='}')depth--;j++}
  const inner=css.slice(open+1,j-1);
  if(prelude.startsWith('@')){nodes.push({type:'at',prelude,children:/^@(media|supports)/.test(prelude)?parseBlocks(inner):null,inner})}
  else nodes.push({type:'rule',selector:prelude,body:inner});
  i=j;
 }
 return nodes;
}

const skinSelector=selector=>splitTop(selector,',').map(s=>{
 s=s.trim();
 return s.startsWith(':root')?SKIN+s.slice(':root'.length):`${SKIN} ${s}`;
}).join(',');

function emit(nodes){
 const out=[];
 for(const node of nodes){
  if(node.type==='rule'){
   const declarations=splitTop(node.body,';').map(d=>d.trim()).filter(d=>HAS_HEX.test(d));
   if(!declarations.length)continue;
   out.push(`${skinSelector(node.selector)}{${declarations.map(d=>d.replace(HEX,warmColour)).join(';')}}`);
  }else if(node.children){
   const inner=emit(node.children);if(inner.length)out.push(`${node.prelude}{${inner.join('\n')}}`);
  }
 }
 return out;
}

export function generate(css){
 const header='/* GENERATED by scripts/generate-admin-kiln.mjs from admin/src/style.css. Do not edit; run `npm run build:admin-skin`. */\n';
 return header+emit(parseBlocks(css)).join('\n')+'\n';
}

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
export const sourcePath=path.join(root,'admin/src/style.css');
export const outputPath=path.join(root,'admin/src/kiln-colors.generated.css');

if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
 const css=generate(fs.readFileSync(sourcePath,'utf8'));
 fs.writeFileSync(outputPath,css);
 console.log(`Wrote ${path.relative(root,outputPath)} (${css.split('\n').length-1} rules)`);
}
